// referenzbilder.js — "Vorher / Arbeitsschritte" and "Nachher" photo pages.
//
// Two pages (#page-referenzVorher, #page-referenzNachher) shared by every
// offer type. Which offers get them is decided in OFFERS (script.js); the
// photos themselves come from referenz-manifest.js, generated by
// scripts/build-referenz-manifest.mjs from src/public/assets/referenz/.
//
// The pages are reference material for the sales conversation, not part of
// the offer: nothing here touches the form state, and getFlowSteps() keeps
// both pages out of Weiter/Zurück.

import { REFERENZ } from "./referenz-manifest.js";

const PAGES = {
  referenzVorher: { kind: "vorher", title: "Vorher & Arbeitsschritte" },
  referenzNachher: { kind: "nachher", title: "Nachher" },
};
const OFFER_LABELS = {
  bu: "Badumbau",
  bwt: "Badewannentür",
  hl: "Handlauf",
  bl: "Badelift",
  ah: "Alltagshilfe",
  hms: "Hausmeisterservice",
  wd: "Winterdienst",
};
const BASE = "/assets/referenz";

// Per page: which category chip is selected. Survives switching pages.
const filterState = {};
let lightbox = null;

const esc = (s) =>
  String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

function currentStep() {
  return (location.hash || "").replace("#", "");
}

function currentOffer() {
  return (typeof window.getCurrentOfferType === "function" && window.getCurrentOfferType()) || null;
}

const src = (offer, kind, file, thumb) =>
  `${BASE}/${offer}/${kind}/${thumb ? "thumbs/" : ""}${encodeURIComponent(file)}`;

function goTo(step, projekt) {
  if (typeof window.setStep === "function") window.setStep(step);
  // setStep only sets location.hash; render now so the card exists to scroll to.
  render(step);
  if (!projekt) return window.scrollTo({ top: 0 });
  // The app's own navigation scrolls to the top after a step change; wait it out.
  setTimeout(() => {
    const card = document.querySelector(`#page-${step} [data-projekt="${CSS.escape(projekt)}"]`);
    if (!card) return;
    card.scrollIntoView({ block: "start" });
    card.classList.remove("ref-flash");
    void card.offsetWidth; // restart the animation
    card.classList.add("ref-flash");
  }, 250);
}

// force=false: skip when the page already shows this offer + filter, so the
// hashchange that follows setStep does not wipe a scroll/flash in progress.
function returnTarget() {
  if (window.__refReturnStep) return window.__refReturnStep;
  const flow = typeof window.getFlowSteps === "function" ? window.getFlowSteps() : [];
  return flow.find((s) => s !== "home") || null;
}

function render(pageId, force = true) {
  const page = document.getElementById(`page-${pageId}`);
  if (!page) return;
  const root = page.querySelector(".ref-root");
  const { kind, title } = PAGES[pageId];
  const offer = currentOffer();
  const key = `${offer}|${filterState[pageId] || ""}|${window.__refReturnStep || ""}`;
  if (!force && root.dataset.key === key) return;
  root.dataset.key = key;
  const data = (offer && REFERENZ[offer]) || {};
  const projects = data[kind] || [];
  const other = kind === "vorher" ? "nachher" : "vorher";
  const otherProjects = new Map((data[other] || []).map((p) => [p.projekt, p]));
  const otherPage = kind === "vorher" ? "referenzNachher" : "referenzVorher";

  // Category chips — only when there is something to choose between.
  const cats = new Map();
  projects.forEach((p) => {
    const c = cats.get(p.kategorie) || { label: p.kategorieLabel, n: 0 };
    c.n += 1;
    cats.set(p.kategorie, c);
  });
  let filter = filterState[pageId];
  if (filter && !cats.has(filter)) filter = filterState[pageId] = null;
  const shown = filter ? projects.filter((p) => p.kategorie === filter) : projects;
  const photoCount = shown.reduce((s, p) => s + p.bilder.length, 0);

  // After a reload the step we came from is gone — fall back to the start of
  // the offer so the way back is always there.
  const returnStep = returnTarget();
  const backBtn = returnStep
    ? `<button type="button" class="ref-back" data-ref-back><span aria-hidden="true">‹</span> Zurück zum Angebot</button>`
    : "";
  const switchSeg = data[other]
    ? `<div class="ref-seg" role="tablist" aria-label="Bildart">
         <button type="button" role="tab" aria-selected="${kind === "vorher"}" data-ref-goto="referenzVorher">Vorher</button>
         <button type="button" role="tab" aria-selected="${kind === "nachher"}" data-ref-goto="referenzNachher">Nachher</button>
       </div>`
    : "";

  const chips =
    cats.size > 1
      ? `<div class="ref-chips" role="toolbar" aria-label="Kategorie filtern">
          <button type="button" class="ref-chip" aria-pressed="${!filter}" data-ref-filter="">Alle <span>${projects.length}</span></button>
          ${[...cats]
            .map(
              ([k, c]) =>
                `<button type="button" class="ref-chip" aria-pressed="${filter === k}" data-ref-filter="${esc(k)}">${esc(c.label)} <span>${c.n}</span></button>`,
            )
            .join("")}
        </div>`
      : "";

  let body;
  if (!projects.length) {
    body = `<div class="ref-empty">Für ${esc(OFFER_LABELS[offer] || "dieses Angebot")} sind noch keine ${kind === "vorher" ? "Vorher-" : "Nachher-"}Bilder hinterlegt.</div>`;
  } else {
    let idx = 0; // running index over the visible photos, for the lightbox
    const cards = shown.map((p) => {
      const twin = otherProjects.get(p.projekt);
      const link = twin
        ? `<button type="button" class="ref-twin" data-ref-goto="${otherPage}" data-ref-projekt="${esc(p.projekt)}">${
            kind === "vorher" ? "Ergebnis ansehen" : `Arbeitsschritte ansehen (${twin.bilder.length})`
          } <span aria-hidden="true">›</span></button>`
        : "";
      const tiles = p.bilder
        .map((b) => {
          const i = idx++;
          const num = kind === "vorher" ? b.label.match(/^(\d+)\./)?.[1] : null;
          const cap = num ? b.label.replace(/^\d+\.\s*/, "") : b.label;
          return `<figure class="ref-tile">
              <button type="button" class="ref-img" data-ref-open="${i}" aria-label="${esc(`Projekt ${p.projekt}, ${b.label} – vergrößern`)}">
                <img loading="lazy" decoding="async" src="${src(offer, kind, b.file, true)}" alt="">
                ${num ? `<span class="ref-stepnum">${num}</span>` : ""}
              </button>
              ${kind === "vorher" ? `<figcaption>${esc(cap)}</figcaption>` : ""}
            </figure>`;
        })
        .join("");
      return `<article class="ref-card" data-projekt="${esc(p.projekt)}">
          <div class="ref-card-head">
            <h3>Projekt ${esc(p.projekt)}</h3>
            <span class="ref-cat">${esc(p.kategorieLabel)}</span>
          </div>
          <div class="ref-tiles">${tiles}</div>
          ${link ? `<div class="ref-card-foot">${link}</div>` : ""}
        </article>`;
    });
    body = `<div class="ref-list">${cards.join("")}</div>`;
  }

  root.innerHTML = `
    <div class="ref-top">
      ${backBtn}
      ${switchSeg}
    </div>
    <div class="ref-head">
      <h2>${esc(title)} <span class="ref-offer">· ${esc(OFFER_LABELS[offer] || "")}</span></h2>
      <p class="ref-sub">${shown.length} ${shown.length === 1 ? "Projekt" : "Projekte"} · ${photoCount} Fotos${
        kind === "vorher" ? " · Ablauf in Schritten" : ""
      }</p>
    </div>
    ${chips}
    ${body}`;

  // Lightbox list = exactly the visible photos, in visible order.
  root._photos = shown.flatMap((p) =>
    p.bilder.map((b) => ({
      full: src(offer, kind, b.file, false),
      thumb: src(offer, kind, b.file, true),
      caption: `Projekt ${p.projekt} · ${p.kategorieLabel}`,
      label: b.label,
    })),
  );
}

function onClick(e) {
  const root = e.target.closest(".ref-root");
  if (!root) return;
  const pageId = root.closest(".page").id.replace(/^page-/, "");

  const open = e.target.closest("[data-ref-open]");
  if (open) return openLightbox(root._photos, Number(open.dataset.refOpen));

  const f = e.target.closest("[data-ref-filter]");
  if (f) {
    filterState[pageId] = f.dataset.refFilter || null;
    render(pageId);
    return;
  }

  const g = e.target.closest("[data-ref-goto]");
  if (g) {
    if (g.dataset.refGoto === pageId && !g.dataset.refProjekt) return;
    // Jumping to a specific project must not be hidden by a category filter.
    if (g.dataset.refProjekt) filterState[g.dataset.refGoto] = null;
    return goTo(g.dataset.refGoto, g.dataset.refProjekt);
  }

  if (e.target.closest("[data-ref-back]") && returnTarget()) {
    window.setStep?.(returnTarget());
  }
}

/* ---------- Lightbox ---------- */

function buildLightbox() {
  const el = document.createElement("div");
  el.className = "ref-lb";
  el.hidden = true;
  el.setAttribute("role", "dialog");
  el.setAttribute("aria-modal", "true");
  el.setAttribute("aria-label", "Bildansicht");
  el.innerHTML = `
    <div class="ref-lb-bar">
      <div class="ref-lb-text"><strong class="ref-lb-label"></strong><span class="ref-lb-cap"></span></div>
      <span class="ref-lb-count"></span>
      <button type="button" class="ref-lb-close" aria-label="Schließen">✕</button>
    </div>
    <div class="ref-lb-stage">
      <img class="ref-lb-img" alt="">
    </div>
    <button type="button" class="ref-lb-nav prev" aria-label="Vorheriges Bild">‹</button>
    <button type="button" class="ref-lb-nav next" aria-label="Nächstes Bild">›</button>`;
  document.body.appendChild(el);

  const img = el.querySelector(".ref-lb-img");
  const state = { photos: [], i: 0 };

  function show(i) {
    const n = state.photos.length;
    state.i = (i + n) % n;
    const p = state.photos[state.i];
    // Thumb first (already cached) so the swipe never shows a blank stage.
    img.src = p.thumb;
    const full = new Image();
    full.onload = () => {
      if (state.photos[state.i] === p) img.src = p.full;
    };
    full.src = p.full;
    el.querySelector(".ref-lb-label").textContent = p.label;
    el.querySelector(".ref-lb-cap").textContent = p.caption;
    el.querySelector(".ref-lb-count").textContent = `${state.i + 1} / ${n}`;
    el.querySelectorAll(".ref-lb-nav").forEach((b) => (b.hidden = n < 2));
    // Warm the neighbour in swipe direction.
    if (n > 1) new Image().src = state.photos[(state.i + 1) % n].full;
  }

  function close() {
    el.hidden = true;
    document.documentElement.classList.remove("ref-lb-open");
    state.opener?.focus?.();
  }

  el.querySelector(".ref-lb-close").addEventListener("click", close);
  el.querySelector(".prev").addEventListener("click", () => show(state.i - 1));
  el.querySelector(".next").addEventListener("click", () => show(state.i + 1));
  el.querySelector(".ref-lb-stage").addEventListener("click", (e) => {
    if (e.target === e.currentTarget) close();
  });
  document.addEventListener("keydown", (e) => {
    if (el.hidden) return;
    if (e.key === "Escape") close();
    else if (e.key === "ArrowLeft") show(state.i - 1);
    else if (e.key === "ArrowRight") show(state.i + 1);
  });

  // Swipe: horizontal = blättern, nach unten = schließen.
  let start = null;
  el.addEventListener(
    "touchstart",
    (e) => {
      if (e.touches.length !== 1) return (start = null);
      start = { x: e.touches[0].clientX, y: e.touches[0].clientY };
    },
    { passive: true },
  );
  el.addEventListener(
    "touchend",
    (e) => {
      if (!start) return;
      const t = e.changedTouches[0];
      const dx = t.clientX - start.x;
      const dy = t.clientY - start.y;
      start = null;
      if (Math.abs(dx) > 50 && Math.abs(dx) > Math.abs(dy)) show(state.i + (dx < 0 ? 1 : -1));
      else if (dy > 90 && Math.abs(dy) > Math.abs(dx)) close();
    },
    { passive: true },
  );

  return {
    open(photos, i) {
      state.photos = photos;
      state.opener = document.activeElement;
      el.hidden = false;
      document.documentElement.classList.add("ref-lb-open");
      show(i);
      el.querySelector(".ref-lb-close").focus({ preventScroll: true });
    },
    close,
    get isOpen() {
      return !el.hidden;
    },
  };
}

function openLightbox(photos, i) {
  if (!photos?.length) return;
  lightbox = lightbox || buildLightbox();
  lightbox.open(photos, i);
}

/* ---------- Wiring ---------- */

function paint() {
  const step = currentStep();
  if (lightbox?.isOpen && !PAGES[step]) lightbox.close();
  if (PAGES[step]) render(step, false);
}

document.addEventListener("click", onClick);
window.addEventListener("hashchange", paint);
paint();
